package ama.task;
import ama.contract.TaskContracts.*;
import org.junit.jupiter.api.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import static org.junit.jupiter.api.Assertions.*;
/** Real concurrent connections; catches duplicate claims, reversed locks and unfenced effects. Never resets fixtures. */
class Task07InheritedTaskLeaseIT {
 Task07InheritedFixture f; JdbcTaskQueue q;
 @BeforeEach void setup(){f=new Task07InheritedFixture();q=f.queue();}
 @Test void twoWorkersCompeteForOneTask() throws Exception {
  var s=f.spec();String id=q.enqueue(s);var go=new CountDownLatch(1);
  try(var es=Executors.newFixedThreadPool(2)){
   var a=es.submit(()->{go.await();return q.claim(s.pool(),"worker-a");});var b=es.submit(()->{go.await();return f.queue().claim(s.pool(),"worker-b");});go.countDown();
   var leases=java.util.stream.Stream.of(a.get(5,TimeUnit.SECONDS),b.get(5,TimeUnit.SECONDS)).flatMap(Optional::stream).toList();
   assertEquals(1,leases.size());assertEquals(id,leases.getFirst().taskId());assertEquals(1,leases.getFirst().attempt());
  }
 }
 @Test void expiredAttemptCannotCommit(){var s=f.spec();var old=f.claimed(q,s);f.expire(old);assertFalse(q.renew(old));var fresh=q.claim(s.pool(),"worker-b");assertTrue(fresh.isPresent());var effects=new AtomicInteger();assertFalse(q.completeWithEffects(old,f.success(s),effects::incrementAndGet));assertTrue(q.completeWithEffects(fresh.orElseThrow(),f.success(s),effects::incrementAndGet));assertEquals(1,effects.get());assertEquals(2,f.j.queryForObject("SELECT COUNT(*) FROM task_attempt WHERE task_id=?",Integer.class,old.taskId()));}
 @Test void pausedOldCompletionLosesToConcurrentCancellation()throws Exception{var s=f.spec();var old=f.claimed(q,s);var ready=new CountDownLatch(1);var proceed=new CountDownLatch(1);try(var worker=Executors.newSingleThreadExecutor()){var result=worker.submit(()->{ready.countDown();proceed.await();return q.completeWithEffects(old,f.success(s),()->fail("old effect ran"));});assertTrue(ready.await(5,TimeUnit.SECONDS));f.advance(s,0,1,false);proceed.countDown();assertFalse(result.get(5,TimeUnit.SECONDS));}}
 @Test void versionEpochAndTombstoneEachFenceOldCompletion(){for(int mode=0;mode<3;mode++){var s=f.spec("FENCE_"+mode,3);var l=f.claimed(q,s);f.advance(s,mode==0?1:0,mode==0?0:1,mode==2);assertFalse(q.renew(l));assertFalse(q.completeWithEffects(l,f.success(s),()->fail("fenced effect ran")));}}
 @Test void sameProducerComparesEntireImmutableSpec(){var s=f.spec();String id=q.enqueue(s);assertEquals(id,q.enqueue(s));assertThrows(IllegalArgumentException.class,()->q.enqueue(new TaskSpec(s.type(),s.pool(),s.subject(),s.producerKey(),s.input(),s.inputFingerprint(),0,1,0,3)));assertEquals(1,f.j.queryForObject("SELECT COUNT(*) FROM durable_task WHERE producer_key=?",Integer.class,s.producerKey()));}
 @Test void missingSubjectAndUnknownOrCrossSubjectTypedInputFailClosed(){var s=f.spec();assertThrows(IllegalArgumentException.class,()->q.enqueue(new TaskSpec(s.type(),s.pool(),new SubjectRef("MEETING",UUID.randomUUID().toString()),s.producerKey(),s.input(),s.inputFingerprint(),0,0,0,3)));var other=f.spec();assertThrows(IllegalArgumentException.class,()->q.enqueue(new TaskSpec(s.type(),s.pool(),s.subject(),s.producerKey(),other.input(),other.inputFingerprint(),0,0,0,3)));}
 @org.junit.jupiter.params.ParameterizedTest @org.junit.jupiter.params.provider.ValueSource(strings={"subject","root","task"}) void heldRowDoesNotBlockOtherCandidate(String lockKind) throws Exception {var a=f.spec("LOCK_POOL",3);var b=f.spec("LOCK_POOL",3);String aid=q.enqueue(a);String bid=q.enqueue(b);var locked=new CountDownLatch(1);var release=new CountDownLatch(1);try(var es=Executors.newSingleThreadExecutor()){var blocker=es.submit(()->f.tx.required(()->{if(lockKind.equals("subject"))f.fences.lock(a.subject(),false);else if(lockKind.equals("root"))f.j.queryForObject("SELECT id FROM meeting WHERE id=? FOR UPDATE",String.class,a.subject().id());else f.j.queryForObject("SELECT id FROM durable_task WHERE id=? FOR UPDATE",String.class,aid);locked.countDown();assertTrue(release.await(5,TimeUnit.SECONDS));return null;}));try{assertTrue(locked.await(5,TimeUnit.SECONDS));var found=q.claim(a.pool(),"other");assertTrue(found.isPresent());assertEquals(bid,found.orElseThrow().taskId());}finally{release.countDown();}blocker.get(5,TimeUnit.SECONDS);}}
 @Test void crashClaimsHaveFiniteAttemptCap(){var s=f.spec("CAP_POOL",2);var a=f.claimed(q,s);f.expire(a);var b=q.claim(s.pool(),"second");assertTrue(b.isPresent());f.expire(b.orElseThrow());assertTrue(q.claim(s.pool(),"third").isEmpty());assertEquals("FAILED",f.j.queryForObject("SELECT state FROM durable_task WHERE id=?",String.class,a.taskId()));}
 @Test void agedLowPriorityWorkAndSafeRetryBackoffProgress(){var low=f.spec("FAIR",2);var high=f.spec("FAIR",2);low=new TaskSpec(low.type(),low.pool(),low.subject(),low.producerKey(),low.input(),low.inputFingerprint(),0,-100,0,2);high=new TaskSpec(high.type(),high.pool(),high.subject(),high.producerKey(),high.input(),high.inputFingerprint(),0,100,0,2);String lowId=q.enqueue(low);q.enqueue(high);f.j.update("UPDATE durable_task SET available_at=UTC_TIMESTAMP(6)-INTERVAL 30 MINUTE WHERE id=?",lowId);var lease=q.claim(low.pool(),"fair").orElseThrow();assertEquals(lowId,lease.taskId());assertTrue(q.complete(lease,new TaskResult(Outcome.RETRYABLE,null,"SAFE_TRANSIENT")));long delay=f.j.queryForObject("SELECT TIMESTAMPDIFF(MICROSECOND,UTC_TIMESTAMP(6),available_at) FROM durable_task WHERE id=?",Long.class,lowId);assertTrue(delay>4000000&&delay<=6000000);var second=q.claim(low.pool(),"fair-2").orElseThrow();assertNotEquals(lowId,second.taskId());}
 @Test void queueDomainAndOutboxRollbackTogether(){var s=f.spec();long before=f.cursor();assertThrows(IllegalStateException.class,()->f.tx.required(()->{q.enqueue(s);new ama.audit.JdbcAuditAdapter(f.source).append(new ama.contract.AuditContracts.AuditEvent("TEST_ACTOR","TASK_TEST",s.subject().id(),0,"SUCCESS",UUID.randomUUID().toString(),java.time.Instant.now()));f.j.update("UPDATE meeting SET needs_generation=1 WHERE id=?",s.subject().id());f.outbox.flush();throw new IllegalStateException();}));assertEquals(0,f.j.queryForObject("SELECT COUNT(*) FROM durable_task WHERE producer_key=?",Integer.class,s.producerKey()));assertEquals(before,f.cursor());assertEquals(0,f.j.queryForObject("SELECT COUNT(*) FROM audit_event WHERE resource_id=?",Integer.class,s.subject().id()));}
 @Test void completionCallbackFailureRollsBackTaskAndOutbox(){var s=f.spec();var l=f.claimed(q,s);long before=f.cursor();assertThrows(IllegalStateException.class,()->q.completeWithEffects(l,f.success(s),()->{f.j.update("UPDATE meeting SET needs_generation=1 WHERE id=?",s.subject().id());throw new IllegalStateException();}));assertEquals("RUNNING",f.j.queryForObject("SELECT state FROM durable_task WHERE id=?",String.class,l.taskId()));assertEquals(0,f.j.queryForObject("SELECT needs_generation FROM meeting WHERE id=?",Integer.class,s.subject().id()));assertEquals(before,f.cursor());}
}
